package com.smritisathi.app.games;
import android.content.*;import com.google.gson.*;import com.smritisathi.app.core.*;
public class GameBase extends BaseGameActivity { void complete(String type,int score,int accuracy,long reaction,int duration){JsonObject b=new JsonObject();b.addProperty("patientId",Session.id(this));b.addProperty("gameType",type);b.addProperty("difficulty","moderate");b.addProperty("score",score);b.addProperty("accuracy",accuracy);b.addProperty("reactionTimeMs",reaction);b.addProperty("durationSeconds",duration);ApiClient.request("POST","/sessions",Session.token(this),b,(ok,d,e)->{if(!ok) { saveOffline(type,score,accuracy,reaction,duration); UI.toast(this,"Saved offline. It will sync when you reconnect.");} else UI.toast(this,"Great job! Score: "+score); showFinish(score,accuracy);});} void saveOffline(String type,int score,int accuracy,long reaction,int duration){OfflineDb.save(this,Session.id(this),type,score,accuracy,reaction,duration);} }
